        display: flex;
        gap: 3rem;

        li {
            position: relative;
            &.menu-item-has-children {
                a {
                    display: flex;
                    align-items: center;
                    gap: .4rem;
                }
            }

            ul {
                position: absolute;
                display: none;
                flex-direction: column;
                background-color: $white;
                gap: 0;
                left: -2rem;
                // box-shadow: $shadow;

                li {
                    a {
                        padding: .3rem 2rem;
                        text-wrap: nowrap;
                        display: block;
                        border-bottom: 1px solid rgba($gray-1, 0.9);

                        &:hover {
                            background-color: $gray-1;
                        }
                    }

                    &:last-child {
                        a {
                            border-bottom: none;
                        }
                    }
                }
            }
        }
    }
  }
}

